function storyForm15(){ return state.questPack?.storyForm15 || state.storyForm15 || null; }

function eveningVolumeAcceptHotfixHtml() {
  const cta = storyForm15()?.eveningVolumeAcceptHotfix;
  if (!cta) return "";
  const day = state.save.dayIndex || 1;
  // antenna failsafe
  const fail = cta.antennaFailsafeOnEvening;
  if (fail && day >= (fail.whenDayMin||4) && ["cold_open_mediate","cold_open_instigate","cold_open_stage"].some(storyFlag)) {
    if (!storyFlag("arc_kite_antenna_complete") && !storyFlag("natural_antenna_complete")) {
      for (const f of fail.setsFlags||[]) state.save.storyFlags[f] = true;
    }
  }
  if (day >= 7) {
    state.save.storyFlags.cold_day2_yielded = true;
    state.save.storyFlags.natural_volume_street = true;
  }
  const w = cta.when || {};
  const ok = day >= (w.orDayIndexMin||999) || whenFlagsOk({...w, orDayIndexMin: undefined});
  // simpler: show if day>=7 OR cold_day2_yielded/antenna done
  const show = day >= 7 || ["cold_day2_yielded","natural_volume_street","natural_antenna_complete","arc_kite_antenna_complete","quest_antenna_complete"].some(storyFlag);
  if (!show || storyFlag("quest_volume_accepted") || storyFlag("arc_volume_war_complete")) return "";
  return (state.locale==="tr" ? cta.html.tr : cta.html.en);
}

